    for k, v in t.get("lambda_true_m1", {}).items(): a(f"* toys at lambda=-1, {CONV[k.split(':')[0]]}, {k.split(':')[1]}: {v['ntoys']} toys; P(q>3.84) = {v['tail']['3.84']['toy']:.3f} (chi2(1): {v['tail']['3.84']['chi2_1']:.3f}); P(q>6.63) = {v['tail']['6.63']['toy']:.4f} ({v['tail']['6.63']['chi2_1']:.4f}); P(q>10.83) = {v['tail']['10.83']['toy']:.4f} ({v['tail']['10.83']['chi2_1']:.4f}); mean q {v['q_mean']:.2f} (chi2(1): 1); Asimov q of the SM-data exclusion {v['q_asimov']:.1f} (Z = {v['Z_asimov']:.2f}), toys at or above it: {v['n_ge_qasimov']} of {v['ntoys']} (the toy count cannot resolve p below about 1/{v['ntoys']}, i.e. about 3.5 sigma)")
    from scipy.stats import poisson as _pz
